<?php require_once 'functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $act=$_POST['action']??'';try{if($act==='add'){ $name=trim($_POST['name']??'');$qty=(int)($_POST['quantity']??0);$unit=$_POST['unit']??'Pieces';$assigned=trim($_POST['assigned_to']??'');if(!$name||$qty<=0||!$assigned)throw new Exception('Fill all fields and use a positive quantity.');db()->prepare('INSERT INTO clothing_items(name,quantity_value,quantity_unit,assigned_to,status) VALUES(?,?,?,?,?)')->execute([$name,$qty,$unit,$assigned,'available']);flash('Clothing item added.');}elseif($act==='bill'){ $id=(int)$_POST['item_id'];$qty=(int)$_POST['quantity'];db()->beginTransaction();$q=db()->prepare('SELECT * FROM clothing_items WHERE id=? FOR UPDATE');$q->execute([$id]);$it=$q->fetch();if(!$it||$qty<=0||$it['quantity_value']<$qty)throw new Exception('Not enough clothing stock.');db()->prepare('UPDATE clothing_items SET quantity_value=quantity_value-? WHERE id=?')->execute([$qty,$id]);db()->prepare('INSERT INTO clothing_billings(item_id,item_name,quantity_billed,unit,billed_by) VALUES(?,?,?,?,?)')->execute([$id,$it['name'],$qty,$it['quantity_unit'],$_SESSION['email']??'']);db()->commit();flash('Clothing bill recorded and stock updated.');}elseif($act==='delete'){db()->prepare('DELETE FROM clothing_items WHERE id=?')->execute([(int)$_POST['id']]);flash('Clothing item deleted.');}}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash($e->getMessage(),'error');}redirect('clothing.php');}$pageTitle='Clothing Inventory';$items=db()->query('SELECT * FROM clothing_items ORDER BY name')->fetchAll();$logs=db()->query('SELECT * FROM clothing_billings ORDER BY date DESC LIMIT 100')->fetchAll();$sales=db()->query('SELECT DATE(date) d,COUNT(*) qty FROM clothing_billings GROUP BY DATE(date) ORDER BY d')->fetchAll();require 'partials/header.php'; ?><div class="clothing-dashboard"><h1 class="dashboard-title">Clothing Inventory Dashboard</h1><div class="panel"><h2>Notifications</h2><?php foreach(get_clothing_alerts() as $a):?><p><?=e($a['message'])?></p><?php endforeach;?></div><div class="grid"><div class="panel"><h2>Clothing Stock Graph</h2><div class="chartbox"><canvas id="clothingStock"></canvas></div></div><div class="panel"><h2>Clothing Sales Graph</h2><div class="chartbox"><canvas id="clothingSales"></canvas></div></div></div><div class="panel"><h2>Restock Clothing</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="add"><input name="name" placeholder="Item name" required><input type="number" name="quantity" min="1" placeholder="Quantity" required><select name="unit"><option>Pieces</option><option>Sets</option></select><input name="assigned_to" placeholder="Assigned to" required><button>Add Clothing</button></form></div><div class="panel"><h2>Bill Clothing Item</h2><form method="post" class="form-grid"><input type="hidden" name="action" value="bill"><select name="item_id" required><option value="">Select item</option><?php foreach($items as $it):?><option value="<?=$it['id']?>"><?=e($it['name'])?> (<?=e($it['quantity_value'])?> <?=e($it['quantity_unit'])?>)</option><?php endforeach;?></select><input type="number" name="quantity" min="1" placeholder="Quantity to bill" required><button>Bill</button></form></div><div class="panel"><h2>Full Clothing Inventory</h2><div class="table-wrap"><table class="inventory-table"><thead><tr><th>Name</th><th>Quantity</th><th>Status</th><th>Restocked On</th><th>Assigned To</th><th>Action</th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><?=e($it['name'])?></td><td><?=e($it['quantity_value'])?> <?=e($it['quantity_unit'])?></td><td><?=e($it['status'])?></td><td><?=e($it['restock_date'])?></td><td><?=e($it['assigned_to'])?></td><td><form method="post" onsubmit="return confirm('Delete item?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$it['id']?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="panel"><h2>Billing History</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit</th><th>Date</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=e($l['item_name'])?></td><td><?=e($l['quantity_billed'])?></td><td><?=e($l['unit'])?></td><td><?=e($l['date'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><script>new Chart(document.getElementById('clothingStock'),{type:'bar',data:{labels:<?=json_encode(array_column($items,'name'))?>,datasets:[{label:'Stock',data:<?=json_encode(array_map('intval',array_column($items,'quantity_value')))?>,backgroundColor:'#f472b6'}]},options:{responsive:true}});new Chart(document.getElementById('clothingSales'),{type:'line',data:{labels:<?=json_encode(array_column($sales,'d'))?>,datasets:[{label:'Bills',data:<?=json_encode(array_map('intval',array_column($sales,'qty')))?>,borderColor:'#f472b6'}]},options:{responsive:true}});</script><?php require 'partials/footer.php'; ?>